<form method="post" action="<?= e(url(['view'=>'documents'])) ?>" class="doc-inline" data-document-interface><?= csrf().hidden('action','document-generate').hidden('source_type',$type).hidden('source_id',$id).hidden('request_key',bin2hex(random_bytes(16))) ?><button class="btn btn-outline theme-secondary secondary"><?= icon('file') ?> <?= e($documentText('PDF-Nachweis erstellen & ablegen')) ?></button></form>
