function documentPanel(\Kulturhus\Verein\Documents $documents,string $type,string $id):void
{
 $documentText=\Kulturhus\Verein\Documents\InterfaceText::text(...);$documentFormat=\Kulturhus\Verein\Documents\InterfaceText::format(...);
 try{$source=$documents->source($type,$id);$rows=$documents->listing(['source_type'=>$type,'source_id'=>$id]);}catch(DomainException){return;}
 $route=['view'=>'documents','source_type'=>$type,'source_id'=>$id];$entryPanel=$type==='entry'; ?>
<section class="card doc-panel iv-no-print" data-document-interface><div class="section-heading"><div><h2><?= e($documentText($entryPanel?'Originalrechnung':'Dokumente & Nachweise')) ?></h2><?php if(!$entryPanel): ?><a class="doc-path" href="<?= e(url(['view'=>'documents','folder'=>$source['folder_id']])) ?>"><?= icon('folder') ?> <?= e($source['path']) ?></a><?php endif ?></div><?php if(!$entryPanel): ?><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url($route)) ?>"><?= e($documentFormat('Ablage öffnen · {count}',['count'=>count($rows)])) ?></a><?php endif ?></div>
<?php if(!$rows): ?><p class="muted"><?= e($documentText('Noch keine Datei zu diesem Vorgang abgelegt.')) ?></p><?php else: ?><details class="doc-attached-list"><summary><?= e($documentFormat('Abgelegte Dateien · {count}',['count'=>count($rows)])) ?></summary><ul class="doc-attached"><?php foreach($rows as $r): ?><li><?= icon('file') ?><a href="<?= e(url(['view'=>'documents','doc'=>$r['id']])) ?>"><?= e($r['title']) ?></a><small><?= e($documentText(\Kulturhus\Verein\Documents::KINDS[$r['kind']])) ?></small><a href="<?= e(url(['document_file'=>$r['id']])) ?>"><?= e($documentText('Herunterladen')) ?></a></li><?php endforeach ?></ul></details><?php endif ?>
<?php if($type==='entry'):$pdfs=array_values(array_filter($rows,static fn(array $row):bool=>($row['state']??'active')==='active'&&($row['mime']??'')==='application/pdf'));if($pdfs):$pdf=$pdfs[0]; ?><details class="doc-inline-preview" open><summary><?= e($documentText('Originalrechnung')) ?></summary><p class="muted"><?= e($documentText('Mit dem Original vergleichen.')) ?></p><?php $previewUrl=url(['document_file'=>$pdf['id'],'revision'=>$pdf['revision'],'preview'=>1]);require dirname(__DIR__, 1).'/../views/Documents/pdf-viewer.php'; ?></details><?php endif;endif ?>
<div class="doc-actions"><?php if($documents->canSource($type,$id,true)): ?><a class="btn btn-solid theme-primary button" href="<?= e(url($route+['new_document'=>1])) ?>"><?= e($documentText('+ Datei zuordnen')) ?></a><details class="doc-extra-actions"><summary><?= e($documentText('Weitere Dokumentaktion')) ?></summary><?php documentRecordButton($type,$id); ?><p class="muted"><?= e($documentText('Ein interner PDF-Nachweis hält den aktuellen Datenstand fest. Originalbelege und ausgestellte Bescheinigungen separat hochladen.')) ?></p></details><?php endif ?></div></section>
<?php }
function documentFields(\Kulturhus\Verein\Documents $documents,array $data,bool $new,bool $withAssignments=true):void
{
 $documentText=\Kulturhus\Verein\Documents\InterfaceText::text(...);$documentFormat=\Kulturhus\Verein\Documents\InterfaceText::format(...);
 ?>
<div class="form-grid" data-document-interface><label class="wide"><?= e($documentText('Dokumenttitel')) ?><input class="form-control" name="title" value="<?= e($data['title']??'') ?>" maxlength="300" required></label><label><?= e($documentText('Dokumentart')) ?><select class="form-control" name="kind"><?php foreach(\Kulturhus\Verein\Documents::KINDS as $key=>$label):if(in_array($key,['record','export','preview'],true)&&($new||$key!==($data['kind']??'')))continue; ?><option value="<?= $key ?>" <?= ($data['kind']??'other')===$key?'selected':'' ?>><?= e($documentText($label)) ?></option><?php endforeach ?></select></label><label><?= e($documentText('Dokumentdatum')) ?><input class="form-control" type="date" name="document_date" value="<?= e($data['document_date']??date('Y-m-d')) ?>" required></label>
<label class="wide"><?= e($documentText('Ordnerpfad')) ?><select class="form-control" name="folder"><option value=""><?= e($documentText('Automatisch anhand von Dokumentart und Zuordnung')) ?></option><?php foreach($documents->writableFolders() as $f): ?><option value="<?= e($f['id']) ?>" <?= ($data['folder']??'')===$f['id']?'selected':'' ?>><?= e($f['path']) ?></option><?php endforeach ?></select></label>
<?php if($new): ?><label><?= e($documentText('Bereich ohne Zuordnung')) ?><select class="form-control" name="scope"><?php foreach(\Kulturhus\Verein\DocumentCatalog::SCOPES as $scope=>$label):if(!$documents->canScope($scope,true))continue; ?><option value="<?= $scope ?>" <?= ($data['scope']??'orga')===$scope?'selected':'' ?>><?= e($documentText($label)) ?></option><?php endforeach ?></select></label><?php else: ?><label><?= e($documentText('Status')) ?><select class="form-control" name="state"><option value="active"><?= e($documentText('Aktiv')) ?></option><option value="archived" <?= ($data['state']??'')==='archived'?'selected':'' ?>><?= e($documentText('Archiviert')) ?></option></select></label><?php endif ?>
<label class="wide"><?= e($documentText('Notiz')) ?><textarea class="form-control" name="notes" maxlength="4000" rows="3"><?= e($data['notes']??'') ?></textarea></label></div>
<?php if($withAssignments)documentAssociations($documents,$data); }
function documentDraftUploads():bool
{
 $text=\Kulturhus\Verein\Documents\InterfaceText::text(...);$tokens=$_POST['live_uploads']['document_files']??[];$present=false;
 if(!is_array($tokens)||!array_is_list($tokens)||count($tokens)>10)return false;
 ?><div data-document-native-uploads><?php foreach($tokens as$token){if(!is_string($token))continue;
 try{$file=\Kulturhus\Verein\LiveUploads::description((string)$_SESSION['actor'],$token,'document-upload-many','document_files');}
 catch(DomainException $error){ ?><p role="alert"><?= e($text($error->getMessage())) ?></p><?php continue;}
 $present=true; ?><p><input type="hidden" name="live_uploads[document_files][]" value="<?= e($token) ?>" data-live-upload-token><span><?= e($file['name']) ?></span> <button type="submit" name="document_browse" value="remove:<?= e($token) ?>" class="btn btn-outline theme-secondary" formnovalidate><?= e($text('Vorbereitete Datei entfernen')) ?></button></p>
 <?php foreach(['document_titles','document_dates','document_groups']as$field)if(is_string($_POST[$field][$token]??null))echo hidden($field.'['.$token.']',$_POST[$field][$token]);
 } ?></div><?php return $present;
}
function documentAssociations(\Kulturhus\Verein\Documents $documents,array $data):void
{
 $documentText=\Kulturhus\Verein\Documents\InterfaceText::text(...);$documentFormat=\Kulturhus\Verein\Documents\InterfaceText::format(...);
 $selected=$data['links']??[];$filters=['query'=>$_POST['document_source_query']??'','type'=>$_POST['document_source_type']??'','page'=>$_POST['document_source_page']??'1'];$failure='';
 try{$all=\Kulturhus\Verein\Web\DocumentAssociationForm::selected(array_replace($_POST,['links'=>$selected]));$page=$documents->sourceChoicePage($filters,$all,(string)($data['id']??''));}
 catch(DomainException $error){$failure=$error->getMessage();$all=array_values(array_filter($selected,'is_string'));$page=$documents->sourceChoicePage([],array_slice($all,0,30),(string)($data['id']??''));}
 $choices=$page['selected'];foreach($page['rows']as$source)$choices[$source['source_type'].':'.$source['source_id']]=$source;
 $visible=[];foreach($selected as$key)if(isset($choices[$key]))$visible[$key]=$choices[$key];foreach($page['rows']as$source)$visible[$source['source_type'].':'.$source['source_id']]=$source;
 ?>
<section class="doc-source-browser" data-document-interface data-document-source-browser>
 <h3><?= e($documentText('Vorgänge finden')) ?></h3><p><?= e($documentText('Sechs Treffer pro Seite. Ausgewählte Zuordnungen bleiben beim Suchen und Blättern erhalten.')) ?></p>
 <?php if($failure!==''): ?><p role="alert"><?= e($documentText($failure)) ?></p><?php endif ?>
 <div class="doc-source-controls"><label><?= e($documentText('Zuordnungen suchen')) ?><input class="form-control" type="search" name="document_source_query" maxlength="150" value="<?= e(is_string($filters['query'])?$filters['query']:'') ?>" placeholder="<?= e($documentText('Belegnummer, Mitglied, Gegenstand …')) ?>"></label>
 <label><?= e($documentText('Vorgangsart')) ?><select class="form-control" name="document_source_type"><option value=""><?= e($documentText('Alle Vorgangsarten')) ?></option><?php foreach(\Kulturhus\Verein\DocumentCatalog::TYPES as$key=>$label): ?><option value="<?= e($key) ?>" <?= $filters['type']===$key?'selected':'' ?>><?= e($documentText($label)) ?></option><?php endforeach ?></select></label>
 <button type="submit" class="btn btn-outline theme-secondary" name="document_browse" value="search" formnovalidate><?= e($documentText('Vorgänge suchen')) ?></button></div>
 <p role="status"><?= e($documentFormat('Vorgangsseite {page} von {pages} · {count} Treffer',['page'=>$page['page'],'pages'=>$page['pages'],'count'=>$page['total']])) ?></p>
 <div class="doc-source-controls"><button type="submit" class="btn btn-outline theme-secondary" name="document_browse" value="previous" formnovalidate <?= $page['page']<=1?'disabled':'' ?>><?= e($documentText('Vorherige')) ?></button><button type="submit" class="btn btn-outline theme-secondary" name="document_browse" value="next" formnovalidate <?= $page['page']>=$page['pages']?'disabled':'' ?>><?= e($documentText('Nächste')) ?></button>
 <label><?= e($documentText('Vorgangsseite')) ?><input class="form-control" name="document_source_page" inputmode="numeric" pattern="[1-9][0-9]{0,8}" value="<?= e($failure!==''&&is_string($filters['page'])?$filters['page']:(string)$page['page']) ?>"></label><button type="submit" class="btn btn-outline theme-secondary" name="document_browse" value="page" formnovalidate><?= e($documentText('Seite öffnen')) ?></button></div>
</section>
<fieldset class="doc-associations" data-document-interface data-doc-source-data="<?= e(json_encode(['choices'=>$choices,'type_labels'=>array_map($documentText,\Kulturhus\Verein\DocumentCatalog::TYPES),'candidates'=>array_map(static fn($s)=>$s['source_type'].':'.$s['source_id'],$page['rows'])],JSON_THROW_ON_ERROR)) ?>"><legend><?= e($documentText('Zu welchem Vorgang gehören die Dokumente?')) ?></legend><p><?= e($documentText('Rechnung, Mitglied, Ausleihe oder einen anderen Vorgang auswählen. Aus einem Vorgang heraus ist die Auswahl bereits vorbelegt. Ohne Auswahl bleiben die Dokumente zunächst im Eingang.')) ?></p><p data-doc-selection-status role="status"></p><div class="doc-choices">
<?php foreach($visible as$key=>$s): ?><label data-doc-choice><input class="check" type="checkbox" name="links[]" value="<?= e($key) ?>" <?= in_array($key,$selected,true)?'checked':'' ?>><span><small><?= e($documentText(\Kulturhus\Verein\DocumentCatalog::TYPES[$s['source_type']])) ?><?= !empty($s['unavailable'])?' · '.e($documentText('Zuordnung derzeit nicht verfügbar')):(!$s['available']?' · '.e($documentText('Historische Zuordnung, Vorgang nicht mehr aktiv')):'') ?></small><?= e($s['label']) ?></span></label><?php endforeach ?></div>
<?php if(!$visible): ?><p><?= e($documentText('Keine passenden Vorgänge. Suche oder Vorgangsart ändern.')) ?></p><?php endif ?></fieldset>
<?php }
